fn split_array(list: &Vec<i32>, l: usize) -> (Vec<i32>, Vec<i32>) {
    // Precondition: 0 < l < list.len()
    assert!(l > 0 && l < list.len(), "split index out of bounds");

    // The first part is list[0..l]
    let first = list[..l].to_vec();

    // The second part is list[l..list.len()]
    let second = list[l..].to_vec();

    (first, second)
}

fn main() {
    let v = vec![10, 20, 30, 40, 50];
    let (a, b) = split_array(&v, 2);
    assert_eq!(a, vec![10, 20]);
    assert_eq!(b, vec![30, 40, 50]);
    println!("First part: {:?}, Second part: {:?}", a, b);
}